<?php
namespace Sis_medico\Http\Controllers\hospital;use Illuminate\Http\Request;use Sis_medico\ClinicalSafetyEvent;use Sis_medico\Exceptions\ClinicalSafetyEventException;use Sis_medico\Http\Controllers\Controller;use Sis_medico\Services\ClinicalAccessControlService;use Sis_medico\Services\ClinicalSafetyEventService;
class ClinicalSafetyEventController extends Controller
{private $service;public function __construct(ClinicalSafetyEventService $s){$this->middleware('auth');$this->service=$s;}public function index(Request $r){if(!$this->service->available())return redirect()->route('hospital.index')->with('error','Aplique la migración de eventos de seguridad.');$encounterId=trim((string)$r->input('encounter_id'));if($encounterId==='')return redirect()->route('hospital.index')->with('error','Abra seguridad clínica desde un episodio.');try{$this->access($encounterId,'SAFETY_EVENT_VIEW',$r);}catch(\Exception $e){return redirect()->route('hospital.index')->with('error',$e->getMessage());}$q=ClinicalSafetyEvent::where('encounter_id',$encounterId)->orderBy('id','desc');$status=trim((string)$r->input('status',''));$category=trim((string)$r->input('category',''));if($status!=='')$q->where('status',$status);if($category!=='')$q->where('category',$category);$events=$q->paginate(30);return view('hospital.clinical_safety.index',compact('events','encounterId'));}
 public function store(Request $r){try{$this->access($r->encounter_id,'SAFETY_EVENT_CREATE',$r);$this->service->create($r->all(),$this->context($r));return back()->with('success','Evento clínico registrado y enviado a seguimiento.');}catch(\Exception $e){return back()->withInput()->with('error',$e->getMessage());}}
 public function notify(Request $r,$id){try{$e=ClinicalSafetyEvent::findOrFail($id);$this->access($e->encounter_id,'SAFETY_EVENT_NOTIFY',$r);$this->service->notify($e,$r->recipient,$this->context($r));return back()->with('success','Notificación registrada.');}catch(\Exception $e){return back()->with('error',$e->getMessage());}}
 public function transition(Request $r,$id){try{$e=ClinicalSafetyEvent::findOrFail($id);$this->access($e->encounter_id,'SAFETY_EVENT_TRANSITION',$r);$this->service->transition($e,$r->status,$r->all(),$this->context($r));return back()->with('success','Seguimiento actualizado.');}catch(\Exception $e){return back()->with('error',$e->getMessage());}}
 private function access($enc,$action,Request $r){app(ClinicalAccessControlService::class)->assertAllowed($enc,$action,array('user'=>auth()->user(),'ip'=>$r->ip()));}private function context(Request $r){return array('actor_id'=>auth()->user()->id,'ip'=>$r->ip());}}
